begin;
select no_plan();
alter table auth.users add column if not exists email text;
do $$declare st uuid;own uuid:=gen_random_uuid();clerk uuid:=gen_random_uuid();req uuid:=gen_random_uuid();begin
 insert into auth.users(id)values(own),(clerk);insert into public.stores default values returning id into st;
 insert into public.staff(user_id,store_id,display_name,role)values(own,st,'Stock owner','owner'),(clerk,st,'Stock clerk','staff');insert into public.portal_admins(user_id,store_id)values(own,st);perform public.seed_store_settings(st,'Stock tests');
 perform set_config('stock.store',st::text,true);perform set_config('stock.owner',own::text,true);perform set_config('stock.clerk',clerk::text,true);perform set_config('stock.request',req::text,true);
 perform set_config('stock.photo',st::text||'/receive/'||clerk::text||'/'||req::text||'/actual.jpg',true);insert into storage.objects(bucket_id,name)values('unit-photos',current_setting('stock.photo'));
 insert into public.store_payout_people(store_id,slot,employee_id)values(st,'paul',own),(st,'jacob',clerk);
 insert into public.portal_payout_rules(store_id,employee_id,method,rate)values(st,own,'percent_profit',20),(st,clerk,'percent_profit',10);
 insert into public.store_settings(store_id,key,value)values(st,'taxRateBps','0')on conflict(store_id,key)do update set value=excluded.value;
end $$;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',current_setting('stock.clerk'),true);
select throws_ok($q$select public.receive_commit(current_setting('stock.request')::uuid,'{"p_quantity":12,"p_brand":"Example","p_title":"Radio","p_cost_cents":200}',array[current_setting('stock.photo')],'{}')$q$,'42501','admin_options_forbidden','clerk cannot set cost');
select throws_ok($q$select public.receive_commit(current_setting('stock.request')::uuid,'{"p_quantity":12,"p_brand":"Example","p_title":"Radio"}',array[current_setting('stock.photo')],'{"location":"99-9-9"}')$q$,'P0002',null,'late failure rolls back entire stocked save');
select is((select count(*)::int from public.units where store_id=current_setting('stock.store')::uuid),0,'no partial SKU after failed save');
select is((select count(*)::int from public.stock_movements where store_id=current_setting('stock.store')::uuid),0,'failed save leaves no movements');
select set_config('stock.result',public.receive_commit(current_setting('stock.request')::uuid,'{"p_quantity":12,"p_brand":"Example","p_model":"Portable Radio","p_title":"Example Portable Radio","p_condition":"New","p_ask_cents":1000,"p_upc":"096801681609"}',array[current_setting('stock.photo')],'{}')::text,true);
select set_config('stock.sku',current_setting('stock.result')::jsonb#>>'{skus,0}',true);
select is(jsonb_array_length(current_setting('stock.result')::jsonb->'skus'),1,'Qty 12 creates one SKU');
select ok((select stocked and qty_on_hand=12 and acquisition_cost_cents is null from public.units where sku=current_setting('stock.sku')),'clerk receives twelve pieces with no cost');
select is((public.stock_info(current_setting('stock.sku'))->>'on_hand')::int,12,'stock card shows twelve');
select ok(not(public.stock_info(current_setting('stock.sku'))?'cost_each_cents'),'clerk stock card omits cost');
select is((public.stock_find_matches('096801681609','Example Portable Radio','New',1000)->0->>'sku'),current_setting('stock.sku'),'repeat UPC finds stocked SKU');
select is((public.receive_commit(current_setting('stock.request')::uuid,'{}','{}','{}')->>'on_hand')::int,12,'lost-response replay returns original balance');
select is((select count(*)::int from public.units where store_id=current_setting('stock.store')::uuid),1,'replay does not create a duplicate SKU');
select throws_ok($q$select public.stock_action(current_setting('stock.sku'),'adjust_set',1,'other: test',gen_random_uuid(),null)$q$,'42501',null,'clerk cannot adjust stock');
select set_config('request.jwt.claim.sub',current_setting('stock.owner'),true);
update public.units set acquisition_cost_cents=200 where sku=current_setting('stock.sku');
select set_config('stock.ticket',gen_random_uuid()::text,true);
select lives_ok($q$select public.finalize_ticket(p_ticket_id=>current_setting('stock.ticket')::uuid,p_lines=>jsonb_build_array(jsonb_build_object('sku',current_setting('stock.sku'),'price_cents',1000,'qty',3)),p_payment_method=>'cash',p_payment_id=>'manual:stock-test',p_cash_cents=>3000,p_card_cents=>0)$q$,'Register sells three pieces');
select is((select qty_on_hand from public.units where sku=current_setting('stock.sku')),9,'on hand drops by three');
select ok((select state='available' from public.units where sku=current_setting('stock.sku')),'remaining stock stays available');
select set_config('stock.sale',(select id::text from public.sales where ticket_id=current_setting('stock.ticket')::uuid),true);
select is((select qty from public.sales where id=current_setting('stock.sale')::bigint),3,'sale records quantity');
select is((select stock_unit_cost_cents from public.sales where id=current_setting('stock.sale')::bigint),200,'sale freezes unit cost');
select is((select cost_cents from public.sale_ledger where id=current_setting('stock.sale')::bigint),600,'ledger uses qty times cost');
select throws_ok($q$select public.finalize_ticket(p_ticket_id=>gen_random_uuid(),p_lines=>jsonb_build_array(jsonb_build_object('sku',current_setting('stock.sku'),'price_cents',1000,'qty',99)),p_payment_method=>'cash',p_payment_id=>'manual:oversell-stock',p_cash_cents=>99000,p_card_cents=>0)$q$,'P0001',null,'cannot oversell');
insert into public.portal_payout_payments(store_id,employee_id,amount_cents,paid_by)values(current_setting('stock.store')::uuid,current_setting('stock.owner')::uuid,480,current_setting('stock.owner')::uuid);
select lives_ok($q$select public.stock_return(current_setting('stock.sale')::bigint,1,'Good condition return',gen_random_uuid())$q$,'return one piece');
select is((select qty_on_hand from public.units where sku=current_setting('stock.sku')),10,'one piece returns to stock');
select is((select price_cents from public.sales where id=current_setting('stock.sale')::bigint),3000,'gross receipt unchanged');
select is((select profit_cents from public.sale_ledger where id=current_setting('stock.sale')::bigint),1600,'net profit reflects two sold pieces');
select is((select sum(amount_cents)::int from public.portal_payout_payments where store_id=current_setting('stock.store')::uuid),480,'paid payments unchanged');
select is((select sum(amount_cents)::int from public.portal_payout_adjustments where store_id=current_setting('stock.store')::uuid),-240,'returned share posts an adjustment');
select throws_ok($q$select public.void_ticket(current_setting('stock.ticket')::uuid,'after partial return',null)$q$,'22023','sale_has_stock_return_use_return_workflow','void cannot restore/refund the already-returned quantity twice');
select lives_ok($q$select public.stock_action(current_setting('stock.sku'),'giveaway',2,'Donation recipient',gen_random_uuid(),null)$q$,'give away two pieces');
select is((select amount_cents from public.portal_expenses where store_id=current_setting('stock.store')::uuid and category='Giveaways'),400,'Giveaways receives quantity times cost');
select set_config('stock.pull',public.stock_action(current_setting('stock.sku'),'defective',1,'Damaged piece',gen_random_uuid(),null)::text,true);
select ok((select not stocked and qty_on_hand=1 and public.unit_is_defective(listing_specs,condition) from public.units where sku=current_setting('stock.pull')::jsonb->>'new_sku'),'defective piece gets a new one-of-one SKU');
select is((select qty_on_hand from public.units where sku=current_setting('stock.sku')),7,'on-hand math remains correct');
select ok(not exists(select 1 from public.units u where u.store_id=current_setting('stock.store')::uuid and u.qty_on_hand<>(select coalesce(sum(delta),0) from public.stock_movements m where m.store_id=u.store_id and m.sku=u.sku)),'all balances equal movement sums');
select ok(not has_table_privilege('authenticated','public.stock_movements','INSERT'),'client cannot forge movements');
select * from finish();
rollback;
